// Rentals (beta, R1; LMB-PLATFORM tasks/todo/2026-11-18-rentals.md). A shop lends things out by the hour or by the
// day: an item has identical units ("3 camera kits"), prices per hour, day and week, a shortest and longest rental,
// time between rentals to check and clean, and the hours it can be picked up and brought back. One copy for the shop's
// pages and the server (functions/shared/rentalRules.js is generated by scripts/build-shared.mjs).
//
// Times are shop times: a day is YYYY-MM-DD in the shop's zone, a time HH:MM. An hourly rental starts on the hour
// or half hour inside the open hours and lasts whole hours; a daily one runs from the opening time of its first day to
// the closing time of its last. A unit is busy from the rental's start to its end plus the cleaning time.
import { zonedTime, addDays, isDay } from "./bookingTimes";

export type RentalBasis = "hour" | "day";
export type RentalItem = {
  id: string;
  name: string;
  description: string;
  photo: string;
  /** Identical units the shop lends out, 1 to MAX_UNITS. */
  units: number;
  /** Rented by the hour or by whole days. */
  basis: RentalBasis;
  /** Prices in the shop's currency's cents; 0 = not offered. At least one of the basis's prices is set. */
  hourMinor: number;
  dayMinor: number;
  weekMinor: number;
  /** Shortest rental: hours for hourly items, days for daily ones. */
  minLength: number;
  /** Longest rental: hours for hourly items, days for daily ones. */
  maxLength: number;
  /** Time kept free after each rental to check and clean, in minutes. */
  cleanMinutes: number;
  /** Pickup and return hours, shop time. */
  opens: string;
  closes: string;
  /** Days ahead people can book. */
  daysAhead: number;
  chargeTax: boolean;
  status: "live" | "draft";
  /** Most the shop may charge the kept card for lateness or damage (R2), cents; 0 = no card kept. */
  depositMinor: number;
  /** Fee for each late hour (hourly items) or day (daily ones), cents; 0 = none. Charged only when the owner taps. */
  lateFeeMinor: number;
  /** Units out for repair (R3), by number from 1. */
  repair?: number[];
  /** Units written off or sold (R3), by number from 1: never rented again, kept so the numbers stay the same. */
  gone?: number[];
};

/** Why a unit is gone, for the owner's own records. */
export type GoneWhy = "writtenOff" | "sold";

export const MAX_ITEMS = 60;
export const MAX_UNITS = 50;
export const MAX_HOURS = 24;
export const MAX_DAYS = 90;
export const MAX_CLEAN_MINUTES = 2880;
export const MAX_DAYS_AHEAD = 365;
/** Spans kept on one item's calendar (past ones are dropped as rentals end). */
export const MAX_SPANS = 600;
export const MINUTE = 60_000;
/** The largest deposit a shop may ask for, cents. */
export const MAX_DEPOSIT_MINOR = 500_000;
/** Time after the end before a return counts as late: hourly items, daily ones. */
export const LATE_GRACE_MINUTES = { hour: 15, day: 60 } as const;
export const HOUR = 60 * MINUTE;

const TIME = /^([01]\d|2[0-3]):([0-5]\d)$/;
const text = (v: unknown, max: number): string => (typeof v === "string" ? v.trim().replace(/\s+/g, " ").slice(0, max) : "");
const whole = (v: unknown, min: number, max: number, fallback: number): number => {
  const n = Number(v);
  return Number.isInteger(n) && n >= min && n <= max ? n : fallback;
};
const money = (v: unknown): number => {
  const n = Number(v);
  return Number.isInteger(n) && n >= 0 && n <= 10_000_000 ? n : -1;
};
export const minutesOf = (hhmm: string): number => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));

/** A rental item as saved, or the problem in the owner's words. */
export function cleanRentalItem(raw: unknown, id = ""): RentalItem | { problem: string } {
  const r = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const name = text(r.name, 100);
  if (!name) return { problem: "Give the item a name." };
  const basis: RentalBasis = r.basis === "day" ? "day" : "hour";
  const prices = { hourMinor: money(r.hourMinor ?? 0), dayMinor: money(r.dayMinor ?? 0), weekMinor: money(r.weekMinor ?? 0) };
  if (Object.values(prices).some((p) => p < 0)) return { problem: "Prices must be amounts of money." };
  if (Object.values(prices).some((p) => p > 0 && p < 50)) return { problem: "A price must be at least 0.50, or left empty." };
  if (basis === "hour" && !prices.hourMinor && !prices.dayMinor) return { problem: "Set an hourly price." };
  if (basis === "day" && !prices.dayMinor && !prices.weekMinor) return { problem: "Set a daily or weekly price." };
  if (basis === "hour") prices.weekMinor = 0;
  if (basis === "day") prices.hourMinor = 0;
  const cap = basis === "hour" ? MAX_HOURS : MAX_DAYS;
  const minLength = whole(r.minLength, 1, cap, 1);
  const maxLength = whole(r.maxLength, minLength, cap, basis === "hour" ? 8 : 14);
  const opens = typeof r.opens === "string" && TIME.test(r.opens) ? r.opens : "10:00";
  const closes = typeof r.closes === "string" && TIME.test(r.closes) ? r.closes : "18:00";
  if (minutesOf(closes) <= minutesOf(opens)) return { problem: "Closing time must be after opening time." };
  if (basis === "hour" && minLength * 60 > minutesOf(closes) - minutesOf(opens)) return { problem: "The shortest rental doesn't fit between your opening and closing times." };
  const depositMinor = money(r.depositMinor ?? 0);
  const lateFeeMinor = money(r.lateFeeMinor ?? 0);
  if (depositMinor < 0 || lateFeeMinor < 0) return { problem: "Prices must be amounts of money." };
  if ((depositMinor > 0 && depositMinor < 50) || (lateFeeMinor > 0 && lateFeeMinor < 50)) return { problem: "A price must be at least 0.50, or left empty." };
  if (depositMinor > MAX_DEPOSIT_MINOR) return { problem: "A deposit can be at most 5,000.00." };
  if (lateFeeMinor > 0 && !depositMinor) return { problem: "Set a deposit too: a late fee is charged to the card kept for it." };
  const units = whole(r.units, 1, MAX_UNITS, 1);
  const repair = Array.isArray(r.repair) ? [...new Set(r.repair.map(Number).filter((n) => Number.isInteger(n) && n >= 1 && n <= units))].sort((a, b) => a - b) : [];
  const gone = Array.isArray(r.gone) ? [...new Set(r.gone.map(Number).filter((n) => Number.isInteger(n) && n >= 1 && n <= units))].sort((a, b) => a - b) : [];
  const fixing = repair.filter((n) => !gone.includes(n));
  const photo = typeof r.photo === "string" && /^https:\/\/\S{1,1900}$/.test(r.photo) ? r.photo : "";
  return {
    id: text(id || r.id, 40), name, description: typeof r.description === "string" ? r.description.trim().slice(0, 4000) : "", photo,
    units, basis, ...prices, minLength, maxLength, depositMinor, lateFeeMinor,
    cleanMinutes: whole(r.cleanMinutes, 0, MAX_CLEAN_MINUTES, 0), opens, closes,
    daysAhead: whole(r.daysAhead, 1, MAX_DAYS_AHEAD, 90), chargeTax: r.chargeTax === true,
    status: r.status === "draft" ? "draft" : "live", ...(fixing.length ? { repair: fixing } : {}), ...(gone.length ? { gone } : {}),
  };
}

/** The cheapest fair price for a rental of this length: hours for hourly items, days for daily ones. */
export function rentalPrice(item: Pick<RentalItem, "basis" | "hourMinor" | "dayMinor" | "weekMinor">, length: number): number {
  if (!(length > 0)) return 0;
  const options: number[] = [];
  if (item.basis === "hour") {
    if (item.hourMinor) options.push(item.hourMinor * length);
    if (item.dayMinor) options.push(item.dayMinor);
  } else {
    if (item.dayMinor) options.push(item.dayMinor * length);
    if (item.weekMinor) {
      const weeks = Math.floor(length / 7);
      const rest = length % 7;
      options.push((weeks + (rest ? 1 : 0)) * item.weekMinor);
      if (item.dayMinor && weeks) options.push(weeks * item.weekMinor + rest * item.dayMinor);
    }
  }
  return options.length ? Math.min(...options) : 0;
}

export type RentalAsk = { day: string; start?: string; hours?: number; endDay?: string };
export type RentalWhen = { startMs: number; endMs: number; length: number; day: string; endDay: string };

/** When an asked rental starts and ends, or the problem in the customer's words. */
export function rentalWhen(item: RentalItem, ask: RentalAsk, zone: string, nowMs: number): RentalWhen | { problem: string } {
  if (!isDay(ask?.day)) return { problem: "Pick a day." };
  const lastDay = addDays(new Date(nowMs).toISOString().slice(0, 10), item.daysAhead + 1);
  if (item.basis === "hour") {
    const start = typeof ask.start === "string" && TIME.test(ask.start) ? ask.start : "";
    const hours = Number(ask.hours);
    if (!start || minutesOf(start) % 30) return { problem: "Pick a start time." };
    if (!Number.isInteger(hours) || hours < item.minLength || hours > item.maxLength) return { problem: `Rent it for ${item.minLength} to ${item.maxLength} hours.` };
    if (minutesOf(start) < minutesOf(item.opens) || minutesOf(start) + hours * 60 > minutesOf(item.closes)) return { problem: "That time is outside the pickup and return hours." };
    const startMs = zonedTime(ask.day, start, zone);
    if (startMs <= nowMs) return { problem: "That time has passed." };
    if (ask.day > lastDay) return { problem: "That day is too far ahead." };
    return { startMs, endMs: startMs + hours * HOUR, length: hours, day: ask.day, endDay: ask.day };
  }
  const endDay = isDay(ask.endDay) ? ask.endDay : ask.day;
  if (endDay < ask.day) return { problem: "The return day must be on or after the pickup day." };
  const days = Math.round((Date.parse(`${endDay}T12:00:00Z`) - Date.parse(`${ask.day}T12:00:00Z`)) / 86_400_000) + 1;
  if (days < item.minLength || days > item.maxLength) return { problem: `Rent it for ${item.minLength} to ${item.maxLength} days.` };
  const startMs = zonedTime(ask.day, item.opens, zone);
  const endMs = zonedTime(endDay, item.closes, zone);
  if (zonedTime(ask.day, item.closes, zone) <= nowMs) return { problem: "That day has passed." };
  if (ask.day > lastDay) return { problem: "That day is too far ahead." };
  return { startMs, endMs, length: days, day: ask.day, endDay };
}

/** One rental on an item's calendar: which unit, from when, busy until (end plus cleaning), held or confirmed. */
/** A unit that can't be rented now: out for repair, or gone. */
export const unitOff = (item: Pick<RentalItem, "repair" | "gone">, unit: number): boolean => Boolean(item.repair?.includes(unit) || item.gone?.includes(unit));

/** Units that can be rented now. */
export const unitsInUse = (item: Pick<RentalItem, "units" | "repair" | "gone">): number => {
  let n = 0;
  for (let unit = 1; unit <= item.units; unit += 1) if (!unitOff(item, unit)) n += 1;
  return n;
};

export type RentalSpan = { id: string; unit: number; from: number; until: number; held?: boolean; holdUntil?: number };

/** The spans that still block: confirmed ones, and holds whose time hasn't run out. */
export const liveSpans = (spans: readonly RentalSpan[] | null | undefined, nowMs: number): RentalSpan[] =>
  (spans || []).filter((s) => s && s.until > nowMs - HOUR && (!s.held || (s.holdUntil || 0) > nowMs));

const overlaps = (a: { from: number; until: number }, b: { from: number; until: number }): boolean => a.from < b.until && b.from < a.until;

/** The first free unit for this time (out-for-repair units never), or 0 when every unit is taken. */
export function freeUnit(item: Pick<RentalItem, "units" | "cleanMinutes" | "repair" | "gone">, spans: readonly RentalSpan[], when: { startMs: number; endMs: number }, nowMs: number, skipId = ""): number {
  const want = { from: when.startMs, until: when.endMs + item.cleanMinutes * MINUTE };
  const busy = liveSpans(spans, nowMs).filter((s) => s.id !== skipId);
  for (let unit = 1; unit <= item.units; unit += 1) {
    if (unitOff(item, unit)) continue;
    if (!busy.some((s) => s.unit === unit && overlaps(s, want))) return unit;
  }
  return 0;
}

/** How many units are free for this time. */
export function unitsFree(item: Pick<RentalItem, "units" | "cleanMinutes" | "repair" | "gone">, spans: readonly RentalSpan[], when: { startMs: number; endMs: number }, nowMs: number): number {
  const want = { from: when.startMs, until: when.endMs + item.cleanMinutes * MINUTE };
  const busy = liveSpans(spans, nowMs);
  let free = 0;
  for (let unit = 1; unit <= item.units; unit += 1) {
    if (unitOff(item, unit)) continue;
    if (!busy.some((s) => s.unit === unit && overlaps(s, want))) free += 1;
  }
  return free;
}

/** Start times on one day for an hourly item, each with the units free for the shortest rental. */
export function hourChoices(item: RentalItem, spans: readonly RentalSpan[], day: string, hours: number, zone: string, nowMs: number): { start: string; free: number }[] {
  const out: { start: string; free: number }[] = [];
  const len = Math.max(item.minLength, Math.min(item.maxLength, Math.round(hours) || item.minLength));
  for (let m = minutesOf(item.opens); m + len * 60 <= minutesOf(item.closes); m += 30) {
    const start = `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
    const when = rentalWhen(item, { day, start, hours: len }, zone, nowMs);
    if ("problem" in when) continue;
    out.push({ start, free: unitsFree(item, spans, when, nowMs) });
  }
  return out;
}

/** For a daily item: each day from `from` for `count` days, with the units free for a one-day rental. */
export function dayChoices(item: RentalItem, spans: readonly RentalSpan[], from: string, count: number, zone: string, nowMs: number): { day: string; free: number }[] {
  const out: { day: string; free: number }[] = [];
  for (let i = 0; i < count; i += 1) {
    const day = addDays(from, i);
    const when = rentalWhen({ ...item, minLength: 1 }, { day, endDay: day }, zone, nowMs);
    out.push({ day, free: "problem" in when ? 0 : unitsFree(item, spans, when, nowMs) });
  }
  return out;
}

export const RENTAL_MESSAGES = {
  taken: "Someone has just taken the last one for that time. Please pick another.",
  closed: "This item can't be rented right now.",
} as const;

/** How many hours (hourly items) or days (daily ones) late a return is, after the grace time. */
export function lateLength(basis: RentalBasis, endMs: number, backMs: number): number {
  const over = backMs - endMs - LATE_GRACE_MINUTES[basis] * MINUTE;
  if (!(over > 0)) return 0;
  return Math.ceil((backMs - endMs) / (basis === "hour" ? HOUR : 24 * HOUR));
}

type FeeRental = { basis: RentalBasis; endMs: number; lateFeeMinor?: number; depositMinor?: number; fees?: { amountMinor: number }[] };

/** The late fee a return at backMs would carry, capped by what is left of the deposit. A suggestion: the owner decides. */
export function lateFeeFor(r: FeeRental, backMs: number): number {
  return Math.min(lateLength(r.basis, r.endMs, backMs) * (r.lateFeeMinor || 0), feeRoom(r));
}

/** What is left of the deposit for fees still to charge. */
export function feeRoom(r: Pick<FeeRental, "depositMinor" | "fees">): number {
  return Math.max(0, (r.depositMinor || 0) - (r.fees || []).reduce((sum, f) => sum + (f.amountMinor || 0), 0));
}
